package com.tablethyme;

import java.math.BigDecimal;
import java.net.URI;
import java.time.*;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import jakarta.servlet.http.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.*;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.stereotype.Component;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.web.servlet.*;
import org.springframework.web.servlet.config.annotation.*;

@RestController @RequestMapping("/api")
public class Api {
 final JdbcTemplate db; final BCryptPasswordEncoder passwords; final ZoneId zone;
 Api(JdbcTemplate db,BCryptPasswordEncoder p,@Value("${app.zone}") String zone){this.db=db;this.passwords=p;this.zone=ZoneId.of(zone);}
 static ResponseStatusException bad(String m){return new ResponseStatusException(HttpStatus.BAD_REQUEST,m);}
 static ResponseStatusException conflict(String m){return new ResponseStatusException(HttpStatus.CONFLICT,m);}
 static ResponseStatusException denied(){return new ResponseStatusException(HttpStatus.FORBIDDEN,"You do not have access to this action.");}
 static String str(Map<String,Object> d,String k,int max){Object v=d.get(k);if(!(v instanceof String)||((String)v).isBlank()||((String)v).length()>max)throw bad("Invalid "+k);return ((String)v).strip();}
 static int number(Map<String,Object> d,String k,int min,int max){try{int n=new BigDecimal(d.get(k).toString()).intValueExact();if(n<min||n>max)throw bad("Invalid "+k);return n;}catch(Exception e){throw bad("Invalid "+k);}}
 static long id(Object n){return ((Number)n).longValue();}
 Map<String,Object> one(String sql,Object...a){var rows=db.queryForList(sql,a);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Record not found.");return rows.get(0);}
 long insert(String sql,Object...args){KeyHolder keys=new GeneratedKeyHolder();db.update(c->{var ps=c.prepareStatement(sql,new String[]{"id"});for(int i=0;i<args.length;i++)ps.setObject(i+1,args[i]);return ps;},keys);return keys.getKey().longValue();}
 @SuppressWarnings("unchecked") Map<String,Object> user(HttpSession s){Object u=s.getAttribute("user");if(u==null)throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Please sign in to continue.");return (Map<String,Object>)u;}
 long ownerHotel(HttpSession s){var u=user(s);if(!"OWNER".equals(u.get("role")))throw denied();return id(one("SELECT id FROM hotels WHERE owner_id=?",u.get("id")).get("id"));}
 Map<String,Object> publicUser(Map<String,Object> u){return Map.of("id",u.get("id"),"name",u.get("name"),"email",u.get("email"),"role",u.get("role"));}
 @GetMapping("/health") Map<String,Object> health(){db.queryForObject("SELECT 1",Integer.class);return Map.of("status","ok");}
 @GetMapping("/auth/me") Map<String,Object> me(HttpSession s){return user(s);}
 @PostMapping("/auth/logout") Map<String,Object> logout(HttpSession s){s.invalidate();return Map.of("ok",true);}
 @PostMapping("/auth/register") @Transactional Map<String,Object> register(@RequestBody Map<String,Object>d,HttpServletRequest req){String name=str(d,"name",80),email=email(d),pass=str(d,"password",100);if(pass.length()<8)throw bad("Use a password of at least 8 characters.");if(db.queryForObject("SELECT COUNT(*) FROM app_users WHERE email=?",Integer.class,email)>0)throw conflict("This email is already registered.");String role="OWNER".equals(d.get("role"))?"OWNER":"CUSTOMER";long uid=insert("INSERT INTO app_users(name,email,password_hash,role) VALUES(?,?,?,?)",name,email,passwords.encode(pass),role);if(role.equals("OWNER"))insert("INSERT INTO hotels(owner_id,name,location,description,cuisine) VALUES(?,?,?,?,?)",uid,name+"’s Hotel","Location to be added","Welcome to our hotel.","Indian");var u=Map.<String,Object>of("id",uid,"name",name,"email",email,"role",role);req.getSession().invalidate();req.getSession(true).setAttribute("user",u);return u;}
 String email(Map<String,Object>d){String e=str(d,"email",190).toLowerCase(Locale.ROOT);if(!e.matches("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$"))throw bad("Enter a valid email address.");return e;}
 @PostMapping("/auth/login") Map<String,Object> login(@RequestBody Map<String,Object>d,HttpServletRequest req){String email=email(d),pass=str(d,"password",100);var rows=db.queryForList("SELECT * FROM app_users WHERE email=?",email);if(rows.isEmpty()||!passwords.matches(pass,(String)rows.get(0).get("password_hash")))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Email or password is incorrect.");var u=publicUser(rows.get(0));req.getSession().invalidate();req.getSession(true).setAttribute("user",u);return u;}
 @GetMapping("/hotels") List<Map<String,Object>> hotels(){return db.queryForList("SELECT * FROM hotels ORDER BY id");}
 @GetMapping("/workspace") Map<String,Object> workspace(@RequestParam(required=false)Long hotelId,@RequestParam(defaultValue="guest")String view,HttpSession session){Map<String,Object> u=session.getAttribute("user")==null?null:user(session);long hid;if(u!=null&&"OWNER".equals(u.get("role"))&&!"guest".equals(view))hid=ownerHotel(session);else{var all=hotels();if(all.isEmpty())return Map.of("hotel",Map.of("id",0,"name","Your hotel awaits","location","","description","No hotels yet.","cuisine","","opens","12:00","closes","23:00"),"tables",List.of(),"menu",List.of(),"hotels",List.of(),"reservations",List.of(),"orders",List.of());hid=hotelId==null?id(all.get(0).get("id")):hotelId;}var hotel=one("SELECT * FROM hotels WHERE id=?",hid);boolean owner=u!=null&&Objects.equals(id(u.get("id")),hotel.get("owner_id")==null?-1L:id(hotel.get("owner_id")));List<Map<String,Object>> rs=u==null?new ArrayList<>():db.queryForList("SELECT * FROM reservations WHERE "+(owner?"hotel_id=?":"user_id=?")+" ORDER BY visit_date,visit_time",owner?hid:u.get("id"));List<Map<String,Object>> reservations=new ArrayList<>();for(var r:rs)reservations.add(reservation(r));List<Map<String,Object>> orders=new ArrayList<>();if(owner)for(var o:db.queryForList("SELECT o.id,o.reservation_id,o.status,r.guest,r.table_id,r.total FROM food_orders o JOIN reservations r ON r.id=o.reservation_id WHERE r.hotel_id=? AND r.status<>'Cancelled'",hid))orders.add(Map.of("id",o.get("id"),"reservationId",o.get("reservation_id"),"status",o.get("status"),"guest",o.get("guest"),"tableId",o.get("table_id"),"total",o.get("total"),"items",items(id(o.get("reservation_id")))));return Map.of("hotel",hotel,"hotels",hotels(),"tables",db.queryForList("SELECT id,name,capacity,status FROM dining_tables WHERE hotel_id=? AND active=TRUE",hid),"menu",db.queryForList("SELECT id,name,category,price,description,image,available FROM menu_items WHERE hotel_id=?",hid),"reservations",reservations,"orders",orders);}
 List<Map<String,Object>> items(long rid){return db.queryForList("SELECT menu_item_id AS id,quantity AS qty,unit_price AS price,item_name AS name FROM order_items WHERE reservation_id=?",rid);}
 Map<String,Object> reservation(Map<String,Object> r){var m=new LinkedHashMap<String,Object>();for(String key:List.of("id","guest","email","guests","status","total"))m.put(key,r.get(key));m.put("date",r.get("visit_date").toString());m.put("time",r.get("visit_time"));m.put("tableId",r.get("table_id"));m.put("hotelId",r.get("hotel_id"));m.put("notes",r.get("notes"));m.put("items",items(id(r.get("id"))));return m;}
 LocalDate date(String d){try{return LocalDate.parse(d);}catch(Exception e){throw bad("Invalid date.");}}
 LocalTime time(String t){try{return LocalTime.parse(t);}catch(Exception e){throw bad("Invalid time.");}}
 boolean overlaps(long tid,LocalDate day,LocalTime at){for(var r:db.queryForList("SELECT visit_time FROM reservations WHERE table_id=? AND visit_date=? AND status IN ('Confirmed','Seated')",tid,day))if(Math.abs(Duration.between(time((String)r.get("visit_time")),at).toMinutes())<90)return true;return false;}
 @GetMapping("/availability") List<Map<String,Object>> available(@RequestParam String date,@RequestParam String time,@RequestParam int guests,@RequestParam(defaultValue="1")long hotelId){LocalDate day=date(date);LocalTime at=time(time);if(guests<1||guests>20)throw bad("Invalid guests.");return db.queryForList("SELECT id,name,capacity,status FROM dining_tables WHERE hotel_id=? AND active=TRUE AND capacity>=? ORDER BY capacity,id",hotelId,guests).stream().filter(t->!overlaps(id(t.get("id")),day,at)).toList();}
 @PostMapping("/reservations") @Transactional Map<String,Object> book(@RequestBody Map<String,Object>d,HttpSession session){var u=user(session);long hid=number(d,"hotelId",1,Integer.MAX_VALUE),tid=number(d,"tableId",1,Integer.MAX_VALUE);var hotel=one("SELECT * FROM hotels WHERE id=?",hid);var table=one("SELECT * FROM dining_tables WHERE id=? AND hotel_id=? AND active=TRUE FOR UPDATE",tid,hid);int guests=number(d,"guests",1,20);if(id(table.get("capacity"))<guests)throw bad("This table does not have enough seats.");LocalDate day=date(str(d,"date",10));LocalTime at=time(str(d,"time",5));if(!LocalDateTime.of(day,at).isAfter(LocalDateTime.now(zone)))throw bad("Choose a future date and time.");if(at.isBefore(time((String)hotel.get("opens")))||at.toSecondOfDay()+5400>time((String)hotel.get("closes")).toSecondOfDay())throw bad("Please choose a 90-minute slot during opening hours.");if(overlaps(tid,day,at))throw conflict("This table has already been booked for that time.");String guest=str(d,"guest",80),email=email(d),notes=d.get("notes")instanceof String?(String)d.get("notes"):"";if(notes.length()>500)throw bad("Notes are too long.");Object raw=d.getOrDefault("items",List.of());if(!(raw instanceof List))throw bad("Invalid order items.");List<?> requested=(List<?>)raw;if(requested.size()>30)throw bad("Too many items.");List<Map<String,Object>> chosen=new ArrayList<>();Set<Long> seen=new HashSet<>();BigDecimal total=BigDecimal.ZERO;for(Object it:requested){if(!(it instanceof Map))throw bad("Invalid order item.");@SuppressWarnings("unchecked")var item=(Map<String,Object>)it;long mid=number(item,"id",1,Integer.MAX_VALUE);int qty=number(item,"qty",1,20);if(!seen.add(mid))throw bad("Duplicate order item.");var dish=one("SELECT * FROM menu_items WHERE id=? AND hotel_id=? AND available=TRUE FOR UPDATE",mid,hid);BigDecimal price=(BigDecimal)dish.get("price");total=total.add(price.multiply(BigDecimal.valueOf(qty)));chosen.add(Map.of("id",mid,"qty",qty,"price",price,"name",dish.get("name")));}long rid=insert("INSERT INTO reservations(hotel_id,user_id,table_id,guest,email,guests,visit_date,visit_time,notes,total) VALUES(?,?,?,?,?,?,?,?,?,?)",hid,u.get("id"),tid,guest,email,guests,day,at.toString(),notes,total);for(var item:chosen)insert("INSERT INTO order_items(reservation_id,menu_item_id,quantity,unit_price,item_name) VALUES(?,?,?,?,?)",rid,item.get("id"),item.get("qty"),item.get("price"),item.get("name"));if(!chosen.isEmpty())insert("INSERT INTO food_orders(reservation_id) VALUES(?)",rid);return reservation(one("SELECT * FROM reservations WHERE id=?",rid));}
 @PatchMapping("/reservations/{id}") @Transactional Map<String,Object> status(@PathVariable long id,@RequestBody Map<String,Object>d,HttpSession s){var u=user(s);var r=one("SELECT * FROM reservations WHERE id=? FOR UPDATE",id);var hotel=one("SELECT owner_id FROM hotels WHERE id=?",r.get("hotel_id"));boolean owner=Api.id(u.get("id"))==Api.id(hotel.get("owner_id"));if(!owner&&Api.id(u.get("id"))!=Api.id(r.get("user_id")))throw denied();String next=str(d,"status",20),prev=(String)r.get("status");boolean allowed=(prev.equals("Confirmed")&&(next.equals("Cancelled")||(owner&&next.equals("Seated"))))||(owner&&prev.equals("Seated")&&(next.equals("Completed")||next.equals("Cancelled")));if(!allowed)throw bad("This status change is not allowed.");db.update("UPDATE reservations SET status=? WHERE id=?",next,id);if(r.get("visit_date").toString().equals(LocalDate.now(zone).toString()))db.update("UPDATE dining_tables SET status=? WHERE id=?",next.equals("Seated")?"Occupied":"Available",r.get("table_id"));return reservation(one("SELECT * FROM reservations WHERE id=?",id));}
 @PutMapping("/owner/hotel") Map<String,Object> hotel(@RequestBody Map<String,Object>d,HttpSession s){long hid=ownerHotel(s);String opens=str(d,"opens",5),closes=str(d,"closes",5);if(!time(opens).isBefore(time(closes)))throw bad("Closing time must be after opening time.");db.update("UPDATE hotels SET name=?,location=?,description=?,cuisine=?,opens=?,closes=? WHERE id=?",str(d,"name",100),str(d,"location",150),str(d,"description",500),str(d,"cuisine",100),opens,closes,hid);return Map.of("ok",true);}
 void tableValues(Map<String,Object>d){str(d,"name",20);number(d,"capacity",1,20);if(!List.of("Available","Occupied","Reserved").contains(d.get("status")))throw bad("Invalid table status.");}
 @PostMapping("/owner/tables") Map<String,Object> addTable(@RequestBody Map<String,Object>d,HttpSession s){long hid=ownerHotel(s);tableValues(d);long id=insert("INSERT INTO dining_tables(hotel_id,name,capacity,status) VALUES(?,?,?,?)",hid,d.get("name"),d.get("capacity"),d.get("status"));return Map.of("id",id);}
 @PutMapping("/owner/tables/{id}") @Transactional Map<String,Object> editTable(@PathVariable long id,@RequestBody Map<String,Object>d,HttpSession s){long hid=ownerHotel(s);one("SELECT id FROM dining_tables WHERE id=? AND hotel_id=? FOR UPDATE",id,hid);tableValues(d);int capacity=number(d,"capacity",1,20);if(db.queryForObject("SELECT COUNT(*) FROM reservations WHERE table_id=? AND status IN ('Confirmed','Seated') AND guests>?",Integer.class,id,capacity)>0)throw conflict("An active reservation requires more seats.");db.update("UPDATE dining_tables SET name=?,capacity=?,status=? WHERE id=?",d.get("name"),capacity,d.get("status"),id);return Map.of("ok",true);}
 @DeleteMapping("/owner/tables/{id}") @Transactional Map<String,Object> deleteTable(@PathVariable long id,HttpSession s){long hid=ownerHotel(s);one("SELECT id FROM dining_tables WHERE id=? AND hotel_id=? FOR UPDATE",id,hid);if(db.queryForObject("SELECT COUNT(*) FROM reservations WHERE table_id=? AND status IN ('Confirmed','Seated')",Integer.class,id)>0)throw conflict("This table has active reservations.");db.update("UPDATE dining_tables SET active=FALSE,name=CONCAT(name,'-',id) WHERE id=?",id);return Map.of("ok",true);}
 Object[] dishValues(Map<String,Object>d){String category=str(d,"category",30);if(!List.of("Starters","Mains","Desserts","Beverages").contains(category))throw bad("Invalid category.");String image=str(d,"image",1000);if(!image.startsWith("https://"))throw bad("Use an HTTPS image URL.");if(!(d.get("available") instanceof Boolean))throw bad("Invalid availability.");return new Object[]{str(d,"name",100),category,number(d,"price",1,100000),str(d,"description",500),image,d.get("available")};}
 @PostMapping("/owner/menu") Map<String,Object> addDish(@RequestBody Map<String,Object>d,HttpSession s){long hid=ownerHotel(s);var a=new ArrayList<>(Arrays.asList(dishValues(d)));a.add(hid);long id=insert("INSERT INTO menu_items(name,category,price,description,image,available,hotel_id) VALUES(?,?,?,?,?,?,?)",a.toArray());return Map.of("id",id);}
 @PutMapping("/owner/menu/{id}") Map<String,Object> editDish(@PathVariable long id,@RequestBody Map<String,Object>d,HttpSession s){long hid=ownerHotel(s);one("SELECT id FROM menu_items WHERE id=? AND hotel_id=?",id,hid);var a=new ArrayList<>(Arrays.asList(dishValues(d)));a.add(id);db.update("UPDATE menu_items SET name=?,category=?,price=?,description=?,image=?,available=? WHERE id=?",a.toArray());return Map.of("ok",true);}
 @PatchMapping("/owner/orders/{id}") @Transactional Map<String,Object> order(@PathVariable long id,@RequestBody Map<String,Object>d,HttpSession s){long hid=ownerHotel(s);var o=one("SELECT o.status FROM food_orders o JOIN reservations r ON r.id=o.reservation_id WHERE o.id=? AND r.hotel_id=? AND r.status<>'Cancelled' FOR UPDATE",id,hid);String next=str(d,"status",20),expected=Map.of("Pending","Preparing","Preparing","Ready","Ready","Served").get(o.get("status"));if(!next.equals(expected))throw bad("Orders must move from Pending to Preparing to Ready to Served.");db.update("UPDATE food_orders SET status=? WHERE id=?",next,id);return Map.of("ok",true);}
}

@Component
class SecurityHeaders implements WebMvcConfigurer {
 // Same-origin JSON APIs + SameSite=Strict session cookies prevent cross-site mutations.
 final Map<String,Deque<Long>> attempts=new ConcurrentHashMap<>();
 @Override public void addInterceptors(InterceptorRegistry registry){registry.addInterceptor(new HandlerInterceptor(){
  @Override public boolean preHandle(HttpServletRequest req,HttpServletResponse res,Object handler){
   res.setHeader("X-Content-Type-Options","nosniff");res.setHeader("X-Frame-Options","DENY");res.setHeader("Referrer-Policy","same-origin");
   if(req.getRequestURI().startsWith("/api/"))res.setHeader("Cache-Control","no-store");
   if(!List.of("GET","HEAD","OPTIONS").contains(req.getMethod())){String origin=req.getHeader("Origin");if(origin!=null){try{URI uri=URI.create(origin);if(!Objects.equals(uri.getAuthority(),req.getHeader("Host")))throw Api.denied();}catch(IllegalArgumentException e){throw Api.denied();}}String type=req.getContentType();if(req.getContentLengthLong()>0&&(type==null||!type.startsWith("application/json")))throw Api.bad("Use application/json.");}
   if(req.getRequestURI().matches("/api/auth/(login|register)")){String ip=req.getRemoteAddr();long now=System.currentTimeMillis();if(attempts.size()>10000)attempts.entrySet().removeIf(e->e.getValue().isEmpty()||e.getValue().peekLast()<now-600000);Deque<Long> times=attempts.computeIfAbsent(ip,k->new ArrayDeque<>());synchronized(times){while(!times.isEmpty()&&times.peekFirst()<now-600000)times.removeFirst();if(times.size()>=30)throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,"Too many attempts. Try again in 10 minutes.");times.addLast(now);}}
   return true;
  }});}
}

@RestControllerAdvice
class Errors {
 @ExceptionHandler(ResponseStatusException.class) ResponseEntity<Map<String,String>> known(ResponseStatusException e){return ResponseEntity.status(e.getStatusCode()).body(Map.of("error",e.getReason()==null?"Request failed.":e.getReason()));}
 @ExceptionHandler(org.springframework.dao.DuplicateKeyException.class) ResponseEntity<Map<String,String>> duplicate(){return ResponseEntity.status(409).body(Map.of("error","This name or email already exists."));}
 @ExceptionHandler({IllegalArgumentException.class,org.springframework.http.converter.HttpMessageNotReadableException.class}) ResponseEntity<Map<String,String>> invalid(){return ResponseEntity.badRequest().body(Map.of("error","Invalid request. Please check your values."));}
}
